// Guides and free frames retain separate layouts when switching modes.
let guideAutoSize=true;
let cropMode='guide',vertical=[],horizontal=[],freeFrames=[],guideDrag=null,activeGuide=null;
const originalRender=render,originalPreviews=previews,originalPointerMove=$('viewport').onpointermove,originalEnd=endDrag;
const controls=document.createElement('div');controls.innerHTML=`<label>크롭 영역 지정 방식<select id="cropMode"><option value="guide">가이드 기반</option><option value="free">자유 배치</option></select></label><div id="guideControls"><p class="hint">선을 추가하면 같은 방향의 선이 균등하게 배치됩니다. 이후 드래그로 그림 중심에 맞추세요.</p><div class="pair"><button id="addVertical">＋ 세로선</button><button id="addHorizontal">＋ 가로선</button></div><label class="link-label"><input id="guideAutoSize" type="checkbox" checked>영역 자동 맞춤 · 겹침·빈틈 없이</label><div id="guidePositions"></div><div class="divider"></div><label>프레임 너비 <output id="gwValue">360 px</output><input id="gw" type="range" min="10" max="2000" value="360"></label><label>프레임 높이 <output id="ghValue">360 px</output><input id="gh" type="range" min="10" max="2000" value="360"></label><p class="hint">자동 맞춤은 가이드 사이의 중간 지점을 경계로 이미지를 빈틈없이 나눕니다. 너비·높이나 비율을 직접 바꾸면 수동 크기로 전환돼요.</p></div>`;
const section=$('ratio').closest('.section');section.insertBefore(controls,section.children[1]);
const guideLayer=document.createElement('div');guideLayer.id='guideLayer';$('stage').append(guideLayer);
const selectedSave=document.createElement('button');selectedSave.id='saveSelected';selectedSave.textContent='선택 프레임 저장';$('individual').before(selectedSave);
const freeOnly=[$('size'),$('add')];const gridButton=$('grid');
function frameSize(){return {w:num('gw',10,100000),h:num('gh',10,100000)}}
function guideCells(positions,extent){
  const sorted=positions.slice().sort((a,b)=>a-b),edges=[0],step=Math.min(1,extent/(sorted.length*2||1));
  for(let i=1;i<sorted.length;i++)edges.push(Math.max(edges[i-1]+step,Math.min(extent-step*(sorted.length-i),(sorted[i-1]+sorted[i])/2)));
  edges.push(extent);return sorted.map((center,i)=>({center,start:edges[i],length:edges[i+1]-edges[i]}));
}
function syncGuideBoxes(){
  const s=frameSize();boxes=[];if(!img)return;
  const vs=guideCells(vertical,img.width),hs=guideCells(horizontal,img.height);
  for(const y of hs)for(const x of vs)boxes.push(guideAutoSize?{x:x.start,y:y.start,w:x.length,h:y.length}:{x:x.center-s.w/2,y:y.center-s.h/2,...s});
  selected=Math.min(selected,boxes.length-1);
  if(guideAutoSize&&boxes.length){const b=boxes[Math.max(0,selected)];for(const [number,range,out,value] of [['cw','gw','gwValue',b.w],['ch','gh','ghValue',b.h]]){if(value>Number($(range).max))$(range).max=Math.ceil(value);$(number).value=$(range).value=Math.round(value);$(out).textContent=Math.round(value)+' px'}}
}
function enableGuideAutoSize(){guideAutoSize=true;$('guideAutoSize').checked=true;$('ratio').value='0'}
$('guideAutoSize').onchange=()=>{snapshot();guideAutoSize=$('guideAutoSize').checked;if(guideAutoSize)$('ratio').value='0';syncGuideBoxes();render()};

function guideState(){return {boxes,cropMode,vertical,horizontal,freeFrames,guideAutoSize,ratio:$('ratio').value,gw:$('gw').value,gh:$('gh').value}}
snapshot=function(){history.push(JSON.stringify(guideState()));if(history.length>40)history.shift()};
function updateModeUI(){const guide=cropMode==='guide';$('cropMode').value=cropMode;$('guideControls').hidden=!guide;freeOnly.forEach(el=>el.hidden=guide);gridButton.textContent=guide?'＋ 격자로 가이드 만들기':'＋ 격자로 영역 만들기';document.body.classList.toggle('guide-mode',guide);document.querySelector('.editorfoot span').textContent=guide?'가이드 선 드래그 · 교점 중심에 프레임 배치':'드래그로 이동 · 모서리로 크기 조절'}
function rebuildPositions(){const list=$('guidePositions');list.replaceChildren();for(const [axis,arr,max] of [['v',vertical,img?.width||1],['h',horizontal,img?.height||1]]){const title=document.createElement('b');title.textContent=(axis==='v'?'세로':'가로')+' 가이드 · '+arr.length+'개';list.append(title);arr.forEach((position,i)=>{const row=document.createElement('div');row.className='guide-position';const label=document.createElement('label');label.textContent=(axis==='v'?'X':'Y')+(i+1);const out=document.createElement('output');out.textContent=Math.round(position)+' px';const slider=document.createElement('input');slider.type='range';slider.min='0';slider.max=max;slider.step='1';slider.value=position;slider.setAttribute('aria-label',(axis==='v'?'세로':'가로')+' 가이드 '+(i+1)+' 위치');slider.onpointerdown=()=>snapshot();slider.onkeydown=e=>{if(e.key.startsWith('Arrow'))snapshot()};slider.oninput=()=>{arr[i]=Number(slider.value);activeGuide={axis,i};out.textContent=slider.value+' px';syncGuideBoxes();render(false)};slider.onchange=()=>previews();label.append(out,slider);const remove=document.createElement('button');remove.textContent='×';remove.title='가이드 삭제';remove.onclick=()=>{snapshot();arr.splice(i,1);activeGuide=null;syncGuideBoxes();rebuildPositions();render()};row.append(label,remove);list.append(row)})}}
function drawGuides(){guideLayer.replaceChildren();if(cropMode!=='guide'||!img)return;for(const [axis,arr] of [['v',vertical],['h',horizontal]])arr.forEach((position,i)=>{const el=document.createElement('div');el.className='guide-line '+axis+(activeGuide?.axis===axis&&activeGuide.i===i?' active':'');el.style[axis==='v'?'left':'top']=position*scale+'px';const label=document.createElement('span');label.textContent=(axis==='v'?'X':'Y')+(i+1);el.append(label);el.onpointerdown=e=>{e.preventDefault();e.stopPropagation();snapshot();activeGuide={axis,i};guideDrag={axis,i,start:axis==='v'?e.clientX:e.clientY,position};$('viewport').setPointerCapture(e.pointerId);drawGuides()};guideLayer.append(el)})}
render=function(withPreview=true){originalRender(withPreview);drawGuides();if(cropMode==='guide')Array.from($('boxes').children).forEach((el,i)=>{el.onpointerdown=e=>{e.preventDefault();selected=i;activeGuide=null;render(false);previews()}})};
previews=function(){originalPreviews();Array.from($('previews').querySelectorAll('.thumb')).forEach((el,i)=>{const download=document.createElement('span');download.className='thumb-save';download.textContent='↓ 저장';download.setAttribute('role','button');download.tabIndex=0;download.onclick=e=>{e.stopPropagation();saveOne(i)};download.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();saveOne(i)}};el.append(download)})};
async function saveOne(i){if(!boxes[i])return toast('저장할 프레임을 선택해 주세요.');let c;try{const {w,h}=getOutputSize(boxes[i]);checkOutputSize(w,h);c=crop(boxes[i],w,h);const blob=await new Promise(r=>c.toBlob(r,'image/'+$('format').value,.95));if(!blob)throw Error();const ext=blob.type==='image/png'?'png':blob.type==='image/jpeg'?'jpg':'webp';save(blob,filename(i).replace(/\.[^.]+$/,'.'+ext));toast((i+1)+'번 프레임을 저장했어요.')}catch{toast('저장하지 못했어요. 출력 크기를 줄여 다시 시도해 주세요.')}finally{if(c)c.width=c.height=1}}
selectedSave.onclick=()=>saveOne(selected);
$('viewport').onpointermove=e=>{if(!guideDrag)return originalPointerMove(e);const {axis,i,start,position}=guideDrag,arr=axis==='v'?vertical:horizontal,max=axis==='v'?img.width:img.height;arr[i]=Math.max(0,Math.min(max,position+((axis==='v'?e.clientX:e.clientY)-start)/scale));syncGuideBoxes();render(false)};
function finishGuideDrag(){if(guideDrag){guideDrag=null;rebuildPositions();previews()}else originalEnd()}
$('viewport').onpointerup=finishGuideDrag;$('viewport').onpointercancel=finishGuideDrag;
function addGuide(axis){if(!requireImage())return;const arr=axis==='v'?vertical:horizontal,other=axis==='v'?horizontal:vertical;if((arr.length+1)*other.length>500||arr.length>=50)return toast('가이드는 방향별 50개, 교점은 500개까지 만들 수 있어요.');snapshot();const extent=axis==='v'?img.width:img.height;arr.push(0);for(let i=0;i<arr.length;i++)arr[i]=(i+1)*extent/(arr.length+1);activeGuide={axis,i:arr.length-1};enableGuideAutoSize();syncGuideBoxes();rebuildPositions();render()}
$('addVertical').onclick=()=>addGuide('v');$('addHorizontal').onclick=()=>addGuide('h');
const oldGrid=gridButton.onclick;gridButton.onclick=()=>{if(cropMode==='free')return oldGrid();if(!requireImage())return;const cols=num('cols',1,50)|0,rows=num('rows',1,50)|0;if(cols*rows>500)return toast('교점은 최대 500개까지 만들 수 있어요.');snapshot();vertical=Array.from({length:cols},(_,i)=>(i+.5)*img.width/cols);horizontal=Array.from({length:rows},(_,i)=>(i+.5)*img.height/rows);selected=0;enableGuideAutoSize();syncGuideBoxes();rebuildPositions();render();toast('가이드 선을 드래그해 그림 중심에 맞춰 주세요.')};
$('cropMode').onchange=()=>{snapshot();if(cropMode==='free')freeFrames=boxes.map(b=>({...b}));cropMode=$('cropMode').value;activeGuide=null;if(cropMode==='guide')syncGuideBoxes();else{boxes=freeFrames.map(b=>({...b}));selected=Math.min(selected,boxes.length-1)}updateModeUI();rebuildPositions();render()};
function syncDimensions(axis){const r=Number($('ratio').value);if(r){if(axis==='h')$('gw').value=Math.round(Number($('gh').value)*r);else $('gh').value=Math.round(Number($('gw').value)/r)}$('cw').value=$('gw').value;$('ch').value=$('gh').value;$('gwValue').textContent=$('gw').value+' px';$('ghValue').textContent=$('gh').value+' px';if(cropMode==='guide'){syncGuideBoxes();render(false)}}
for(const [id,axis] of [['gw','w'],['gh','h']]){$(id).onpointerdown=()=>snapshot();$(id).onkeydown=e=>{if(e.key.startsWith('Arrow'))snapshot()};$(id).oninput=()=>syncDimensions(axis);$(id).onchange=()=>previews()}
const oldRatio=$('ratio').onchange,oldWidth=$('cw').onchange,oldHeight=$('ch').onchange;$('ratio').onchange=()=>{if(cropMode==='free')return oldRatio();snapshot();syncDimensions('w');previews()};
for(const [id,axis,old] of [['cw','w',oldWidth],['ch','h',oldHeight]])$(id).onchange=()=>{if(cropMode==='free')return old();snapshot();$(axis==='w'?'gw':'gh').value=$(id).value;syncDimensions(axis);previews()};
$('undo').onclick=()=>{if(!history.length)return;const s=JSON.parse(history.pop());if(Array.isArray(s)){boxes=s}else{({boxes,cropMode,vertical,horizontal,freeFrames}=s);guideAutoSize=s.guideAutoSize??false;$('guideAutoSize').checked=guideAutoSize;if(s.ratio!=null)$('ratio').value=s.ratio;$('gw').value=s.gw;$('gh').value=s.gh;$('cw').value=s.gw;$('ch').value=s.gh;$('gwValue').textContent=s.gw+' px';$('ghValue').textContent=s.gh+' px'}selected=Math.min(selected,boxes.length-1);updateModeUI();rebuildPositions();render()};
function resetGrid(){if(!vertical.length&&!horizontal.length&&!boxes.length&&!freeFrames.length)return;snapshot();vertical=[];horizontal=[];freeFrames=[];boxes=[];activeGuide=null;selected=-1;guideDrag=null;drag=null;rebuildPositions();render();toast('모든 격자선과 크롭 영역을 지웠어요.')}
const gridReset=document.createElement('button');gridReset.id='gridReset';gridReset.className='wide';gridReset.textContent='격자 초기화';gridButton.after(gridReset);gridReset.onclick=resetGrid;
$('clear').onclick=resetGrid;
document.addEventListener('keydown',e=>{if(typeof correctionBusy!=='undefined'&&correctionBusy)return;if(cropMode!=='guide'||/INPUT|SELECT|TEXTAREA|BUTTON/.test(e.target.tagName))return;if(!['Delete','Backspace','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.stopImmediatePropagation();e.preventDefault();if(!activeGuide)return;const arr=activeGuide.axis==='v'?vertical:horizontal,i=activeGuide.i;if(e.key==='Delete'||e.key==='Backspace'){snapshot();arr.splice(i,1);activeGuide=null}else{const delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-1,ArrowDown:1}[e.key];snapshot();arr[i]=Math.max(0,Math.min(activeGuide.axis==='v'?img.width:img.height,arr[i]+delta*(e.shiftKey?10:1)))}syncGuideBoxes();rebuildPositions();render()},true);
const originalLoad=load;load=async function(file){if(!file)return;const before=img;await originalLoad(file);const timer=setInterval(()=>{if(img!==before){clearInterval(timer);vertical=[];horizontal=[];freeFrames=[];activeGuide=null;enableGuideAutoSize();const limit=Math.max(img.width,img.height)*2;for(const id of ['gw','gh'])$(id).max=limit;$('gw').value=$('cw').value;$('gh').value=$('ch').value;$('gwValue').textContent=$('gw').value+' px';$('ghValue').textContent=$('gh').value+' px';rebuildPositions();render()}},30);setTimeout(()=>clearInterval(timer),10000)};
$('help').onclick=()=>toast('가이드 기반: 격자로 가이드를 만든 뒤 선을 드래그하거나 위치 슬라이더로 조절하세요. 교점마다 프레임이 생깁니다. 너비·높이를 각각 조절하려면 자유 비율을 선택하세요. 자유 배치: 각 프레임을 직접 이동·크기 조절하세요. 미리보기의 저장 버튼으로 하나씩 내보낼 수 있어요.');
$('ratio').value='0';updateModeUI();rebuildPositions();render();
